#---------------------------#
# DEBUG AREA 1
@token       = debug-area-1
@name        = DEBUG Area 1
@level       = 1
@size        = 14 x 26
@sheet       = mmrpg-overworld-2k25
#---------------------------#
@portals[]   = spawn(6-10)
@portals[]   = goto__debug-area-1n(6-8, 8-13)
@portals[]   = goto__debug-area-1s(6-12, 5-3)
@portals[]   = goto__debug-area-1w(4-10, 17-5)
@portals[]   = goto__debug-area-1e(8-10, 3-5)
@portals[]   = goto__debug-area-0(6-23, 10-7)
#---------------------------#
@field       = gentle-countryside
#---------------------------#
@encounters  = met(2),trille-bot(1)
#---------------------------#
@terrain[]   = grass(gentle-countryside)
@terrain[]   = subspace(prototype-subspace)
#---------------------------#
@habitats[]  = met(grass)
@habitats[]  = trille-bot(subspace)
#---------------------------#
@mechas[]    = west-portal-mecha(4-10, rockscotch)
@mechas[]    = east-portal-mecha(8-10, antlin-g)
@mechas[]    = north-portal-mecha(6-8, frosty-throwman)
@mechas[]    = south-portal-mecha(6-12, octone)
#---------------------------#
@bosses[]    = subspace-portal-boss(6-23, trill, 50, speed)
#---------------------------#
@buttons[]   = subspace-button(6-24, purple, up, set-group-terrain, subspace-path, subspace)
#---------------------------#
@events[]    = auto-heal(4-8, healpad, any, trigger-effects, restore-team-energy, restore-team-weapons)
@events[]    = auto-reset(8-8, resetpad, any, trigger-effects, reset-team-attack, reset-team-defense, reset-team-speed)
@events[]    = light-platform-left(5-2, lightpad-left, any, drop-zone, item:light-program, activate-player-platform)
@events[]    = light-platform-middle(6-2, lightpad-middle, any, drop-zone, item:light-heart, activate-player-platform)
@events[]    = light-platform-right(7-2, lightpad-right, any, drop-zone, item:copy-core, activate-player-platform)
#---------------------------#
@groups[]    = central-area(4-8...8-12)
@groups[]    = light-boundary(5-18...7-20)
@groups[]    = item-corridor(2-2...12-4, 6-5, 6-6)
@groups[]    = item-corridor-2(11-8...13-12, 10-10)
@groups[]    = item-island-1(2-15...3-16)
@groups[]    = item-island-2(11-15...13-17)
@groups[]    = subspace-path(6-14, 6-15, 6-16, 6-17)
@groups[]    = subspace-path-ends(6-13, 6-18)
@groups[]    = under-subspace-button(5-24, 5-25, 6-25, 7-25, 7-24)
@groups[]    = no-encounters(central-area, item-corridor, item-corridor-2, item-island-1, item-island-2, light-boundary, under-subspace-button, subspace-path, subspace-path-ends)
